#!/bin/bash

set -e  # Abort in case of errors

# RM directories containing Python auto-generated bytecode
rm -rf $(find . -type d -name __pycache__)

# RM pytest cache directory
rm -rf .pytest_cache

# RM files auto-generated by ANTLR4
rm -rf gelb/antlr4/generated_code/*
rm -rf gelb/antlr4/grammars/.antlr/
